const page = (title, body) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><style>${PAGE_CSS}</style></head><body><div class="wrap"><div class="brand">Acme · Client query review</div>${body}</div></body></html>`;
const messagePage = (title, cls, html) => page(title, `<h1>${esc(title)}</h1><div class="${cls}">${html}</div>`);

// The query details shown at the top of the review page.
const queryCard = (row) => {
  const reasons = String(row['Human review reasons'] || '').split(/;\s*/).filter(r => r && r !== 'None');
  const english = !/^english$/i.test(String(row['Language'] || 'English'));
  return `<div class="card"><div class="meta">
<div>Query</div><div>${esc(row['Query ID'])}</div>
<div>Priority</div><div><span class="pill ${esc(row['Priority'])}">${esc(row['Priority'])}</span> &nbsp;${esc(row['Category'])}</div>
<div>From</div><div>${esc(row['Sender'] || 'Unknown')} · ${esc(row['Client'])} · via ${esc(row['Channel'])}</div>
<div>Account owner</div><div>${esc(row['Account owner'] || 'Not assigned')}</div>
<div>Received</div><div>${esc(row['Received'])}</div>
<div>Reply due</div><div>${esc(row['SLA due'])}</div>
<div>Language</div><div>${esc(row['Language'] || 'English')}</div>
<div>Summary</div><div>${esc(row['Summary'])}</div>
</div>
${reasons.length ? `<label>Why this needs a person</label><ul>${reasons.map(r => `<li>${esc(r)}</li>`).join('')}</ul>` : ''}
${row['Client message'] ? `<label>Client's message</label><div class="quote">${esc(row['Client message'])}</div>` : ''}
${english && row['AI draft (English)'] ? `<label>English version of the AI's draft (for checking)</label><div class="quote">${esc(row['AI draft (English)'])}</div>` : ''}
</div>`;
};

// Step 1 (anyone with the alert link): see the query and the draft, then ask for a personal sign-off link.
// The link is sent by private Slack message to the person chosen, so you can only sign off as yourself.
const requestPage = (row, o) => {
  const approvers = listApprovers(o.approvers);
  const err = o.error ? `<div class="bad">${esc(o.error)}</div><br>` : '';
  return page('Review reply · ' + row['Query ID'], `
<h1>Reply to ${esc(row['Client'])}</h1>${err}
${queryCard(row)}
<div class="card"><label>Suggested reply</label><div class="quote">${esc(row['AI draft reply'])}</div></div>
<form class="card" method="post" action="${esc(o.action)}">
<input type="hidden" name="id" value="${esc(row['Query ID'])}"><input type="hidden" name="t" value="${esc(o.token)}"><input type="hidden" name="mode" value="link">
<label for="reviewer">To edit and sign off this reply, confirm who you are</label>
<div class="inline"><select id="reviewer" name="reviewer" required><option value="">Choose your name…</option>${approvers.map(a => `<option value="${esc(a)}">${esc(a)}</option>`).join('')}</select>
<button class="send">Send me a sign-off link</button></div>
<div class="note">We'll send a one-time link by private Slack message to the person you choose. It works once and expires after ${LINK_MINUTES} minutes, so each person can only sign off as themselves.</div>
</form>`);
};

// Step 2 (opened from the private Slack link): the signer is already known, so they edit and approve or decline.
const reviewPage = (row, o) => {
  const reply = o.reply != null ? o.reply : row['AI draft reply'];
  const ref = String(row['Reply ref'] || '');
  const via = ref.startsWith('gmail:') ? 'email' : ref.startsWith('slack:') ? 'Slack' : '';
  const english = !/^english$/i.test(String(row['Language'] || 'English'));
  const warn = o.violations && o.violations.length
    ? `<div class="warn"><b>Check this wording before it goes to the client.</b> The reply ${o.violations.map(esc).join(' and ')}. These are the same rules the AI's drafts are held to. Edit the reply, or send it as written on your name.</div>` : '';
  const ph = hasPlaceholders(reply) ? `<div class="warn">The reply still contains a placeholder in [square brackets]. Fill it in before approving.</div>` : '';
  const err = o.error ? `<div class="bad">${esc(o.error)}</div><br>` : '';
  return page('Review reply · ' + row['Query ID'], `
<h1>Reply to ${esc(row['Client'])}</h1>${err}${warn}${ph}
${queryCard(row)}
<form class="card" method="post" action="${esc(o.action)}">
<input type="hidden" name="id" value="${esc(row['Query ID'])}"><input type="hidden" name="t" value="${esc(o.token)}"><input type="hidden" name="k" value="${esc(o.k)}">
${o.violations && o.violations.length ? '<input type="hidden" name="override" value="1">' : ''}
<label for="reply">Reply to the client${english ? ' (in their language)' : ''}, edit as needed</label>
<textarea id="reply" name="reply">${esc(reply)}</textarea>
<div class="note">${via ? `Approving sends this reply to the client by ${via}, and records your name against it.` : 'Demo query: approving records the decision and your name, but there is no real client to send it to.'}</div>
<div class="signer">:: Signing off as <b>${esc(o.signer)}</b> · identity confirmed by your private Slack link</div>
<div class="btns">
<button class="approve" name="decision" value="approve">${o.violations && o.violations.length ? 'Send as written, on my name' : 'Approve &amp; send'}</button>
<button class="decline" name="decision" value="decline">Don't send, I'll handle it myself</button>
</div></form>`).replace(':: ', '&#128274; ');
};
// ===== end shared helpers =====

// Handles two things from the review page:
//  1. A request for a sign-off link: sends a one-time link by private Slack message to the person chosen.
//  2. A decision made from that link: the signer comes from the link itself, never from a name typed on the page.
// Then the usual checks: query still open, and the (possibly edited) reply still meets policy.
const req = $('Route by trigger').first().json;
const b = req.body || {};
const rows = $input.all().map(i => i.json).filter(r => r && r['Query ID']);
const action = `${req.cfg_review_base}/client-decision`;
const reply = String(b.reply || '').replace(/\r\n/g, '\n').trim();
const decision = b.decision === 'decline' ? 'decline' : 'approve';
const row = rows.find(r => r['Query ID'] === b.id);

const out = (o) => [{ json: { send_via: 'none', update: false, reviewer: '', ...o, query_id: b.id, decision, reply } }];

if (!b.t || b.t !== req.cfg_token) return out({ html: messagePage('This link is not valid', 'bad', 'The review form is incomplete or has expired. Open it again from the Slack alert.') });
if (!row) return out({ html: messagePage('Query not found', 'bad', `No query with reference <b>${esc(b.id)}</b> is in the log.`) });
if (!isOpen(row['Status'])) return out({ html: messagePage('Already decided', 'ok', `<b>${esc(row['Query ID'])}</b> was already handled: ${esc(row['Decision'] || row['Status'])}${row['Approved by'] ? ` by <b>${esc(row['Approved by'])}</b>` : ''}. Nothing was sent twice.`) });

// ---- 1. Someone asks for a sign-off link ----
if (b.mode === 'link') {
  const name = String(b.reviewer || '').trim();
  const ask = (error) => out({ html: requestPage(row, { action, token: req.cfg_token, approvers: req.cfg_approvers, error }) });
  if (!listApprovers(req.cfg_approvers).includes(name)) return ask('Please choose your name from the approver list.');
  const slackId = parseMap(req.cfg_approver_slack_ids)[name];
  if (!/^[UW][A-Z0-9]{6,}$/.test(slackId || '')) return ask(`${name} doesn't have a Slack account linked yet, so they can't sign off. Ask the workflow admin to add their Slack member ID in Settings.`);
  const links = signoffStore();
  const k = Array.from({ length: 4 }, () => Math.floor(Math.random() * 0x100000000).toString(16).padStart(8, '0')).join('');
  links[k] = { id: row['Query ID'], name, exp: Date.now() + LINK_MINUTES * 60 * 1000 };
  const url = `${req.cfg_review_base}/client-review?id=${encodeURIComponent(row['Query ID'])}&t=${encodeURIComponent(req.cfg_token)}&k=${k}`;
  return out({
    send_via: 'dm', dm_user: slackId,
    dm_text: `:lock: *Your sign-off link* for \`${row['Query ID']}\` · ${row['Client']}\n<${url}|Open the reply to review, edit and approve it>\n_Only for ${name}. It works once and expires in ${LINK_MINUTES} minutes. Don't forward it._`,
    html: messagePage('Check your Slack', 'ok', `A one-time sign-off link for <b>${esc(row['Query ID'])}</b> has been sent by private Slack message to <b>${esc(name)}</b>.<br><br>Open it from Slack to edit and approve the reply. It works once and expires in ${LINK_MINUTES} minutes.`),
  });
}

// ---- 2. A decision: who is signing off comes only from their personal link ----
const s = checkSignoff(b.k, row['Query ID']);
if (!s) return out({ html: requestPage(row, { action, token: req.cfg_token, approvers: req.cfg_approvers, error: 'Your sign-off link has expired or was already used. Nothing was sent. Request a new link below.' }) });
const reviewer = s.name;
const again = (extra) => out({ reviewer, html: reviewPage(row, { action, token: req.cfg_token, k: b.k, signer: reviewer, reply, ...extra }) });
const useLink = () => { delete signoffStore()[String(b.k)]; };

if (decision === 'decline') {
  useLink();
  return out({ send_via: 'none', update: true, row, outcome: 'declined', reviewer });
}
if (!reply) return again({ error: 'The reply is empty.' });
if (hasPlaceholders(reply)) return again({ error: 'The reply still contains a placeholder in [square brackets]. Fill it in, then approve.' });

// The same guardrails apply to people. A person can override them, but only knowingly and on their name.
const violations = checkPolicy(reply);
if (violations.length && b.override !== '1') return again({ violations });

useLink();
const ref = String(row['Reply ref'] || '');
const send_via = ref.startsWith('gmail:') ? 'gmail' : ref.startsWith('slack:') ? 'slack' : 'none';
const parts = ref.split(':');
return out({
  send_via, update: true, row, reviewer, outcome: send_via === 'none' ? 'approved-demo' : 'approved',
  overridden: violations,
  gmail_message_id: send_via === 'gmail' ? parts.slice(1).join(':') : '',
  slack_channel: send_via === 'slack' ? parts[1] : '',
  slack_thread: send_via === 'slack' ? parts.slice(2).join(':') : '',
});

// ===== Shared helpers: the same rules, times and page layout are used by several nodes =====
const TZ = 'Europe/London';
const OPEN_STATUSES = ['Awaiting approval', 'Escalated – awaiting approval', 'Overdue – awaiting approval', 'Send failed – retry needed'];
const isOpen = s => OPEN_STATUSES.includes(String(s || '').trim());
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

// Times are stored in the sheet as readable London time, e.g. "2026-10-07 14:05"
const nowLdn = () => DateTime.now().setZone(TZ);
const fmtTime = dt => dt.setZone(TZ).toFormat('yyyy-MM-dd HH:mm');
const parseTime = s => {
  if (!s) return null;
  let dt = DateTime.fromFormat(String(s).trim(), 'yyyy-MM-dd HH:mm', { zone: TZ });
  if (!dt.isValid) dt = DateTime.fromISO(String(s).trim(), { zone: TZ });
  return dt.isValid ? dt : null;
};
// Working hours: Mon-Fri 09:00-17:30 London. SLA clocks only run inside them.
const addWorkingMinutes = (start, minutes) => {
  let t = start.setZone(TZ), left = minutes;
  for (let guard = 0; guard < 60 && left > 0; guard++) {
    const open = t.set({ hour: 9, minute: 0, second: 0, millisecond: 0 });
    const close = t.set({ hour: 17, minute: 30, second: 0, millisecond: 0 });
    if (t.weekday > 5 || t >= close) { t = t.plus({ days: 1 }).set({ hour: 9, minute: 0, second: 0, millisecond: 0 }); continue; }
    if (t < open) t = open;
    const avail = close.diff(t, 'minutes').minutes;
    if (left <= avail) return t.plus({ minutes: left });
    left -= avail;
    t = t.plus({ days: 1 }).set({ hour: 9, minute: 0, second: 0, millisecond: 0 });
  }
  return t;
};

// Policy check: rules every client reply must meet, whoever wrote it (AI or a person).
const NEGATED = /\b(?:don'?t|do not|no need to|please don'?t|never|avoid)\b/i;
const POLICY = [
  { rule: 'promises a specific deadline', test: s => /\bby (?:the )?(?:end of (?:the )?(?:day|week)|eod|cob|close of business|tomorrow|tonight|today|this (?:afternoon|evening|week)|(?:mon|tues|wednes|thurs|fri|satur|sun)day|\d{1,2}(?::\d{2})?\s?(?:am|pm))\b/i.test(s) || /\bwithin (?:the next )?(?:\d+|an?|one|two|few|24|48)\s*(?:minutes?|hours?|days?|business days?|working days?)\b/i.test(s) || /\b(?:later )?(?:today|tomorrow) (?:morning|afternoon|evening)\b/i.test(s) },
  { rule: 'asks the client for screenshots or attachments', test: s => /\b(?:screenshots?|screen ?grabs?|attach(?:ment)?s?|export)\b/i.test(s) && !NEGATED.test(s) },
  { rule: 'confirms a product defect before investigation', test: s => /\b(?:this|it) (?:is|was|'s) (?:a |definitely a |indeed a )?(?:known )?(?:bug|defect|fault|error on our (?:side|end))\b/i.test(s) || /\bwe(?:'ve| have)? (?:caused|broken)\b/i.test(s) },
  { rule: 'offers a refund, discount or credit', test: s => /\b(?:refund|discount|credit note|free (?:month|of charge)|waive)\b/i.test(s) && !NEGATED.test(s) },
];
const checkPolicy = text => {
  const parts = String(text || '').split(/(?<=[.!?])\s+|\n+/);
  return POLICY.filter(p => parts.some(p.test)).map(p => p.rule);
};
const hasPlaceholders = text => /\[[^\]]+\]/.test(String(text || ''));

