const TZ = 'Europe/London';
const OPEN_STATUSES = ['Awaiting approval', 'Escalated – awaiting approval', 'Overdue – awaiting approval', 'Send failed – retry needed'];
const isOpen = s => OPEN_STATUSES.includes(String(s || '').trim());
const nowLdn = () => DateTime.now().setZone(TZ);
const parseTime = s => {
  if (!s) return null;
  let dt = DateTime.fromFormat(String(s).trim(), 'yyyy-MM-dd HH:mm', { zone: TZ });
  if (!dt.isValid) dt = DateTime.fromISO(String(s).trim(), { zone: TZ });
  return dt.isValid ? dt : null;
};
const sl = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); // Slack-safe text

const cfg = $('Route by trigger').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r['Query ID']);
const now = nowLdn();
const since = now.minus({ hours: 24 });
const P = ['High', 'Medium', 'Low'];
const ORDER = { High: 0, Medium: 1, Low: 2 };
const ICON = { High: ':red_circle:', Medium: ':large_yellow_circle:', Low: ':large_green_circle:' };
const count = (list, key) => list.reduce((m, r) => (m[r[key]] = (m[r[key]] || 0) + 1, m), {});
const byP = list => P.map(p => `${p} ${list.filter(r => r['Priority'] === p).length}`).join(' · ');

const reviewUrl = id => `${cfg.cfg_review_base}/client-review?id=${encodeURIComponent(id)}&t=${encodeURIComponent(cfg.cfg_token)}`;
const idLink = r => `*<${r['Slack alert'] || reviewUrl(r['Query ID'])}|${r['Query ID']}>*`;
const ownerName = r => sl(String(r['Account owner'] || 'unassigned').replace(/\s*\(.*\)\s*$/, ''));
const late = mins => mins < 90 ? `${Math.round(mins)} min` : mins < 60 * 36 ? `${Math.round(mins / 60)} h` : `${Math.round(mins / 1440)} days`;

const fresh = rows.filter(r => { const d = parseTime(r['Received']); return d && d >= since; });
const open = rows.filter(r => isOpen(r['Status']));
const overdue = open.filter(r => { const d = parseTime(r['SLA due']); return d && d < now; })
  .sort((a, b) => (ORDER[a['Priority']] ?? 3) - (ORDER[b['Priority']] ?? 3) || String(a['SLA due']).localeCompare(String(b['SLA due'])));
const decided = rows.filter(r => { const d = parseTime(r['Approved at']); return d && d >= since && r['Approved by'] && !/^Automation/.test(r['Approved by']); });
const approvers = count(decided, 'Approved by');
const cats = Object.entries(count(fresh, 'Category')).sort((a, b) => b[1] - a[1]).slice(0, 4).map(([c, n]) => `${sl(c)} ${n}`).join(' · ');
